import{j as e}from"./index-BF5TKH9M.js";import{C as s,S as t,a as n,F as o,b as r,c as a}from"./CaseStudyLayout-QXENH29O.js";import"./react-vendor-CqPR5u_r.js";import"./markdown-vendor-BtwvP2vC.js";import"./analytics-CbY8X2g3.js";const u=()=>e.jsxs(s,{title:"Hermes",subtitle:"hermes-agent, Nous Research's open-source harness, running self-hosted with a nightly eval loop and a weekly self-improvement cron built around it — nothing changes without my approval.",tech:["hermes-agent","Langfuse","LiteLLM","Telegram","HITL","Evals","WhisperX","Obsidian","Cron","LLM-as-Judge"],repoLink:{href:"https://github.com/NousResearch/hermes-agent",label:"hermes-agent on GitHub (Nous Research)"},children:[e.jsxs(t,{title:"Why This Exists",children:[e.jsx("p",{children:"None of this started as a plan. A Mac Mini bought for a desktop, a Raspberry Pi to stop paying for SaaS, then an inference box to wire it all together — at some point three unrelated purchases became a homelab running my own AI agents. Voice memos turn into structured notes before I've put my phone away, and none of it needs me checking in on it manually."}),e.jsxs("p",{children:["The agent runtime itself, ",e.jsx("code",{children:"hermes-agent"}),", is Nous Research's open-source harness (MIT-licensed). I didn't write it — I deployed it, and I built the observability and safety layer around it. That distinction matters: running an agent unattended for weeks is a different problem than running one in a notebook while you watch. You need to know if it's actually doing a good job, not just whether it's still running."]})]}),e.jsxs(t,{title:"Architecture",children:[e.jsxs("p",{children:["Three machines, three jobs. A ",e.jsx("strong",{children:"Mac Mini (16GB)"})," runs the orchestrator: the cron scheduler and the Telegram bot. It doesn't have the RAM to host a capable model itself, so every reasoning call routes over the LAN through ",e.jsx("strong",{children:"LiteLLM"})," to the ",e.jsx("strong",{children:"Framework Desktop"}),", whose unified-memory GPU serves local models (qwen-27b and qwen-35b-a3b) over a hand-patched llama.cpp build. A"," ",e.jsx("strong",{children:"Raspberry Pi"})," handles monitoring. Cloud providers (Nous Portal, OpenRouter, OpenAI) are wired in as a deliberate fallback — for anything sensitive, or when local hits its usage limit — not the default path."]}),e.jsx("p",{children:"Memory is files-first: an Obsidian vault the agents read directly, with a quick-context profile loaded at every session start. I tried a vector-memory layer (mem0-oss + ChromaDB) first and pulled it — recall accuracy came in under the published community benchmarks and memories weren't accumulating the way they were supposed to. Markdown files turned out to be the more honest memory layer for this scale. Every call, local or cloud, is traced end-to-end in Langfuse — tool calls, LLM chains, timing, token counts."})]}),e.jsxs(t,{title:"The Eval Loop and Self-Improvement",children:[e.jsxs("p",{children:["This part is mine, not the harness's. A nightly cron pulls every conversation's execution trace from Langfuse and has an LLM judge score it on three criteria: ",e.jsx("code",{children:"task_completed"})," ","(0/1), ",e.jsx("code",{children:"tool_calls_efficient"})," (1–5), and ",e.jsx("code",{children:"response_quality"})," (1–5). Scores post back to Langfuse, broken out by cron vs. interactive sessions, so a quality regression shows up as part of normal operation instead of getting discovered later."]}),e.jsx("p",{children:"A second, weekly cron closes the loop: it pulls the last 30 days of low-scoring turns, clusters them by theme, and proposes specific edits to the agent's own system prompt — sent to Telegram, never applied automatically."}),e.jsxs("p",{children:["One real run: ",e.jsx("strong",{children:"11 low-quality turns"})," clustered into"," ",e.jsx("strong",{children:"3 patterns"}),", producing ",e.jsx("strong",{children:"3 proposed edits"}),". Two were approved and landed in the prompt — ",e.jsx("em",{children:'"lead with the answer"'})," and"," ",e.jsx("em",{children:'"complete every action chain, no preamble-only turns."'})," The third was rejected: every turn in that cluster turned out to be an automated cron delivery, and the proposed fix didn't actually apply to that context. The loop found a real pattern and recommended the wrong fix for it. Catching that before it landed is the actual point of keeping a human in the loop — the system proposes, it doesn't decide."]})]}),e.jsxs(n,{title:"What Broke: The Judge Was Overthinking It",children:[e.jsx("p",{children:"The nightly judge is a pure classification task — three small scores, no open-ended reasoning required. I first ran it through the judge model's default thinking mode, and it started timing out at around three minutes per trace. The model wasn't wrong, it was just reasoning its way through a decision that didn't need reasoning, burning tokens on a task that should have taken seconds."}),e.jsxs("p",{children:["The fix was smaller than the symptom suggested: route the judge through the"," ",e.jsx("code",{children:"ollama_chat/"})," path with ",e.jsx("code",{children:"think:false"}),` instead of the default endpoint, and the same scoring pass drops from minutes to seconds per trace. It's a good reminder that "smarter mode" isn't free, and that matching the model's reasoning budget to the actual shape of the task is part of the job, not a nice-to-have.`]})]}),e.jsx(o,{src:"/images/case-studies/hermes-langfuse-traces.png",alt:"Langfuse tracing table showing spans for Hermes turns: LiteLLM requests, LLM calls, and tool calls with latencies and a cost column reading $0.00 on every row",caption:"The trace table behind the eval loop: every turn decomposes into gateway, LLM, and tool spans — and the cost column reads $0.00 all the way down, because every call runs on local hardware."}),e.jsx(t,{title:"Honest Limitations",children:e.jsxs("ul",{children:[e.jsx("li",{children:"The 27B model is bandwidth-bound at roughly 12 tokens/sec — a memory-bandwidth limit of the hardware, not a config problem I can tune away. A smaller quant would trade quality for speed; I haven't made that trade."}),e.jsx("li",{children:"Vector memory (mem0-oss + ChromaDB) didn't work well enough to keep — recall accuracy was too low, and I replaced it with the simpler files-first approach above."}),e.jsx("li",{children:"A prior MCP bridge between Hermes and other tooling was dropped as redundant once direct vault access and eval scripts covered the same ground — one less moving part."}),e.jsx("li",{children:"This is a solo homelab project, not a customer deployment: real scale, multi-tenant load, and adversarial inputs are things I'd want to pressure-test before claiming this generalizes past one operator's use."})]})}),e.jsxs(r,{children:[e.jsx(a,{value:"3",label:"Homelab Nodes"}),e.jsx(a,{value:"$0",label:"Marginal Cost / Call"}),e.jsx(a,{value:"11",label:"Low-Quality Turns Clustered"}),e.jsx(a,{value:"2 of 3",label:"Prompt Edits Applied"})]})]});export{u as default};
